def solve(items: list) -> str:
    if not items:
        return "none"

    best_sku = items[0][0]
    best_total = items[0][1] * items[0][2]

    for sku, quantity, unit_cents in items[1:]:
        total = quantity * unit_cents
        if total > best_total:
            best_sku = sku
            best_total = total

    return best_sku

