import re

def solve(log: str) -> str:
    counts = {}
    for line in log.splitlines():
        match = re.match(r"^\d{2}:\d{2}:\d{2}\s+ERROR\s+([^:\s]+):", line)
        if match:
            service = match.group(1)
            counts[service] = counts.get(service, 0) + 1

    if not counts:
        return "none"

    highest = max(counts.values())
    return min(service for service, count in counts.items() if count == highest)

def solve(errors: int, lines: int) -> int:
    if lines == 0:
        return 0
    return (200 * errors + lines) // (2 * lines)

def solve(csv: str) -> list:
    rows = []
    row = []
    field = []
    quoted = False
    pos = 0

    while pos < len(csv):
        char = csv[pos]

        if quoted:
            if char == '"':
                if pos + 1 < len(csv) and csv[pos + 1] == '"':
                    field.append('"')
                    pos += 1
                else:
                    quoted = False
            else:
                field.append(char)
        elif char == '"' and not field:
            quoted = True
        elif char == ',':
            row.append(''.join(field))
            field = []
        elif char == '\n' or char == '\r':
            row.append(''.join(field))
            field = []
            if row != ['']:
                rows.append(row)
            row = []
            if char == '\r' and pos + 1 < len(csv) and csv[pos + 1] == '\n':
                pos += 1
        else:
            field.append(char)

        pos += 1

    if field or row:
        row.append(''.join(field))
        if row != ['']:
            rows.append(row)

    return [[record[0], record[1], int(record[2]), int(record[3])]
            for record in rows[1:]]

def solve(rows: list) -> dict:
    totals = {}
    for row in rows:
        country = row[1]
        totals[country] = totals.get(country, 0) + row[2] * row[3]
    return totals

def solve(totals: dict) -> str:
    if not totals:
        return "none"
    return min(totals, key=lambda country: (-totals[country], country))

