def solve(label: str, top: str, big: list) -> str:
    ids = ",".join(map(str, big)) if big else "none"
    return f"{label}: top {top}, {len(big)} big orders: {ids}"

import re

def solve(thread: str) -> dict:
    counts = {}
    for line in thread.splitlines():
        match = re.match(r"\[\d{2}:\d{2}\] ([^:]+): ", line)
        if match:
            name = match.group(1)
            counts[name] = counts.get(name, 0) + 1
    return counts

def solve(counts: dict) -> str:
    if not counts:
        return "none"
    return max(sorted(counts), key=counts.get)

