    if tone == "negative":
        return "urgent" if intent in ("refund", "cancel") else "normal"
    return "low"

def solve(scores: str) -> list:
    result = []
    for line in scores.splitlines():
        name, separator, score = line.partition(":")
        if separator:
            result.append([name.strip(), int(score.strip())])
    return result

import math

def solve(parsed: list) -> int:
    if not parsed:
        return 0
    mean = sum(item[1] for item in parsed) / len(parsed)
    return math.floor(mean + 0.5)

def solve(parsed: list) -> int:
    scores = sorted(item[1] for item in parsed)
    if not scores:
        return 0
    return scores[(len(scores) - 1) // 2]

def solve(parsed: list) -> dict:
    counts = {'A': 0, 'B': 0, 'C': 0, 'D': 0, 'F': 0}
    for record in parsed:
        score = record[1]
        if score >= 90:
            counts['A'] += 1
        elif score >= 80:
            counts['B'] += 1
        elif score >= 70:
            counts['C'] += 1
        elif score >= 60:
            counts['D'] += 1
        else:
            counts['F'] += 1
    return counts

def solve(parsed: list) -> str:
    if not parsed:
        return "none"
    highest_score = max(score for name, score in parsed)
    return min(name for name, score in parsed if score == highest_score)

def solve(mean: int, median: int, grades: dict, top: str, tone: str) -> str:
    result = (
        f"mean {mean}, median {median}, "
        f"A{grades['A']} B{grades['B']} C{grades['C']} "
        f"D{grades['D']} F{grades['F']}, top {top}"
    )
    if tone == "negative":
        result += " - review"
    return result

def solve(stock: str) -> list:
    result = []
    for line in stock.splitlines():
        item, on_hand, minimum, unit_cents = (part.strip() for part in line.split("|"))
        result.append([item, int(on_hand), int(minimum), int(unit_cents)])
    return result

def solve(rows: list) -> dict:
    return {
        item: 2 * minimum - on_hand
        for item, on_hand, minimum, unit_cents in rows
        if on_hand < minimum
    }

def solve(order: dict, rows: list) -> int:
    prices = {item: unit_cents for item, on_hand, minimum, unit_cents in rows}
    return sum(quantity * prices[item] for item, quantity in order.items())

import re

def solve(minutes: str) -> list:
    actions = []
    pattern = re.compile(r"ACTION\s+@(\S+)\s+due\s+(\d{4}-\d{2}-\d{2}):\s*(.*)")
    for line in minutes.splitlines():
        match = pattern.fullmatch(line)
        if match:
            actions.append([match.group(1), match.group(2), match.group(3)])
    return actions

def solve(actions: list) -> str:
    counts = {}
    for action in actions:
        name = action[0]
        counts[name] = counts.get(name, 0) + 1

    if not counts:
        return "none"

    return min(counts, key=lambda name: (-counts[name], name))
